using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace ScreenCraft
{
    static class ToolbarSettingsTests
    {
        static System.Collections.Generic.IEnumerable<Control> Children(Control root){foreach(Control c in root.Controls){yield return c;foreach(var d in Children(c))yield return d;}}
        static void Click(Button button){typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        static bool Key(CaptureOverlay overlay,Keys keys){var message=Message.Create(IntPtr.Zero,0x100,IntPtr.Zero,IntPtr.Zero);return (bool)typeof(CaptureOverlay).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(overlay,new object[]{message,keys});}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("toolbar/settings clone isolates order hidden flags and key dictionaries",delegate{var settings=new ToolbarSettings();var clone=settings.Clone();clone.Move(3,0);clone.Hidden=new[]{"Rect"};clone.Keys["Arrow"]="G";check(settings.Order[0]=="Rect"&&settings.Keys["Arrow"]=="A"&&settings.Hidden.Contains("Counter"),"settings aliased");check(clone.Validate()==null&&clone.Order[0]=="Arrow","move invalid");});
            run("toolbar/duplicates reserved keys malformed orders and corrupt configs rejected",delegate{var s=new ToolbarSettings();s.Keys["Arrow"]="R";check(s.Validate()!=null,"duplicate");s.Keys["Arrow"]="P";check(s.Validate()!=null,"reserved pin");s.Keys["Arrow"]="C";check(s.Validate()!=null,"reserved color");s.Keys["Arrow"]="G";s.Order[0]="Unknown";check(s.Validate()!=null&&ToolbarSettings.Safe(s).Order[0]=="Rect","corrupt fallback");});
            run("toolbar/tool shortcut recorder accepts one letter and protects global chords",delegate{using(var input=new HotkeyInput{ToolShortcutMode=true}){input.RecordKey(Keys.G);check(input.Text=="G","letter not recorded");input.RecordKey(Keys.Control|Keys.R);check(input.Text=="G","modifier chord became tool key");input.RecordKey(Keys.P);input.RecordKey(Keys.C);check(input.Text=="G","reserved key accepted");input.RecordKey(Keys.Back);check(input.Text=="","clear failed");}});
            run("toolbar/preference roundtrip retains order hidden tools and remapped keys",delegate{var preferences=new Preferences();preferences.Toolbar.Move(3,0);preferences.Toolbar.Keys["Arrow"]="G";preferences.Toolbar.Hidden=new[]{"Rect","Redact"};var store=new PreferenceStore(Path.Combine(output,"toolbar-settings"));store.Save(preferences);var loaded=store.Load();check(loaded.Toolbar.Validate()==null&&loaded.Toolbar.Order[0]=="Arrow"&&loaded.Toolbar.Hidden.Contains("Rect")&&loaded.Toolbar.Keys["Arrow"]=="G","toolbar preferences lost");});
            run("toolbar/hidden dialog reorder checkbox key and confirm invoke real UI events",delegate{using(var dialog=new ToolbarSettingsDialog(new ToolbarSettings())){var list=Children(dialog).OfType<CheckedListBox>().Single();list.SetItemChecked(0,false);list.SelectedIndex=3;dialog.MoveSelection(-1);var field=Children(dialog).OfType<HotkeyInput>().Single();field.RecordKey(Keys.G);Click(Children(dialog).OfType<Button>().Single(b=>b.Text=="确认工具栏"));check(dialog.Result!=null&&dialog.Result.Hidden.Contains("Rect")&&dialog.Result.Order[2]=="Arrow"&&dialog.Result.Keys["Arrow"]=="G"&&!dialog.Visible,"toolbar UI did not save controls");}});
            run("toolbar/general settings save preserves toolbar pending config",delegate{var p=new Preferences();p.Toolbar.Keys["Arrow"]="G";p.Toolbar.Hidden=new[]{"Rect"};Preferences saved=null;using(var dialog=new SettingsDialog(p,"fixture",delegate(Preferences value){saved=value;return "keep hidden";})){Click(Children(dialog).OfType<Button>().Single(b=>b.Text=="保存并应用"));check(saved!=null&&saved.Toolbar.Keys["Arrow"]=="G"&&saved.Toolbar.Hidden.Contains("Rect"),"global settings reset toolbar");}});
            run("toolbar/overlay consumes ordered visible tools and remapped keys",delegate{var settings=new ToolbarSettings();settings.Move(3,0);settings.Hidden=new[]{"Rect","Redact"};settings.Keys["Arrow"]="G";using(var overlay=new CaptureOverlay(new Bitmap(1000,700),new Rectangle(0,0,1000,700),new Rectangle(100,100,700,400),new[]{new Rectangle(0,0,1000,660)},settings)){var all=Children(overlay).OfType<CaptureIconButton>().ToArray();check(all.Any(b=>b.AccessibleName=="箭头 G")&&!all.Any(b=>b.AccessibleName=="矩形 R"),"order visibility not applied");var main=Children(overlay).OfType<FlowLayoutPanel>().First(p=>p.Controls.OfType<CaptureIconButton>().Any(b=>b.AccessibleName=="箭头 G"));check(main.Controls.OfType<CaptureIconButton>().First().AccessibleName=="箭头 G","visual order stale");check(Key(overlay,Keys.G)&&overlay.AnnotationCanvas.Tool==Tool.Arrow,"remap ignored");check(Key(overlay,Keys.R)&&overlay.AnnotationCanvas.Tool==Tool.Rect,"hidden key inaccessible");check(!overlay.Visible,"overlay shown");}});
            run("toolbar/text editing keeps remapped letters from selecting tools",delegate{var settings=new ToolbarSettings();settings.Keys["Arrow"]="G";using(var overlay=new CaptureOverlay(new Bitmap(1000,700),new Rectangle(0,0,1000,700),new Rectangle(100,100,700,400),new[]{new Rectangle(0,0,1000,660)},settings)){var c=overlay.AnnotationCanvas;c.SetTool(Tool.Text);var mark=ScreenCraftTests.Mark(Tool.Text,130,130,250,170);mark.Text="输入 G";c.AddAnnotation(mark);c.EditNote();check(c.Typing,"fixture not editing");Key(overlay,Keys.G);check(c.Tool==Tool.Text&&c.Typing,"typing selected arrow");}});
        }
    }
}
